class GreatestCommonDivisor{
    // int GCD;    //Greatest Common Divisor 
    public int getGCD(int maxNum, int minNum){
        if(minNum == 0){
            return maxNum;
        }else{
            return getGCD(minNum, (maxNum % minNum));
        }
    }
}

