  }

  int dp(int at)
  {
    if (at == n) return 1;
    if (at > n) return 0;
    if (dp[at] != -1) return dp[at];
    int cnt = 0;
    if (!a[at+1]) cnt += dp(at+1);
    cnt %= mod;
    if (!a[at+2]) cnt += dp(at+2);
    cnt %= mod;
    return dp[at] = cnt % mod;
  }

