				new BufferedReader(new InputStreamReader(System.in))) {
			String[] s = bf.readLine().split(" ");
			int N = Integer.parseInt(s[0]);
			int M = Integer.parseInt(s[1]);
			boolean[] flag = new boolean[N+1];
