            if (more <= num && num <= less) {
                sum += i;
            }
        }

        System.out.println(sum);
    }

    public static int getKetaNoWa(int number) {
        int sum = 0;

        for (int i = 5; i >= 0; i--) {
            int tmp = number / (int)Math.pow(10, i);
            sum += tmp;
            number -= tmp * (int)Math.pow(10, i);
        }

        return sum;
    }
}

